package com.oms.order.service;
import org.junit.jupiter.api.*;
import java.util.*;
import static com.oms.order.service.OrderValues.*;
import static com.oms.order.service.RefundValues.*;
import static org.junit.jupiter.api.Assertions.*;
class RefundBundleReturnTest {
 RefundGoodsServiceTest f;RefundBundleReturns service;long bundle;
 @BeforeAll static void start(){RefundGoodsServiceTest.start();}
 @BeforeEach void setup(){f=new RefundGoodsServiceTest();f.setup();f.f.db.update("DELETE FROM oms_refund_bundle_return");f.f.db.update("DELETE FROM oms_order_bundle");long order=f.f.order;bundle=f.f.repo.insert("INSERT INTO oms_order_bundle(company_code,order_id,platform_oid,sku_sn,goods_name,quantity,payment,revision,snapshot) VALUES ('VERIFY',?,'987654321012345679','S','Kit',1,20,1,'{}')",order);f.f.db.update("UPDATE oms_order_line SET quantity=2,reserved_quantity=2,bundle_id=?,component_quantity=2 WHERE order_id=?",bundle,order);f.f.db.update("UPDATE oms_order_shipment_line SET quantity=2,shipped_quantity=2");long b=f.f.repo.insert("INSERT INTO oms_order_line(company_code,order_id,platform_oid,sku_sn,goods_name,quantity,payment,reserved_quantity,bundle_id,component_quantity) VALUES ('VERIFY',?,'987654321012345679','B','Part B',1,0,1,?,1)",order,bundle);long shipment=f.f.db.queryForObject("SELECT id FROM oms_order_shipment",Long.class);f.f.db.update("INSERT INTO oms_order_shipment_line(company_code,shipment_id,order_line_id,platform_oid,sku_sn,goods_name,quantity,shipped_quantity,allocation_id,stock_source_id,store_code,batch_id,source_type) VALUES ('VERIFY',?,?,'987654321012345679','B','Part B',1,1,2,2,'V',2,'PUBLIC_EXTRA')",shipment,b);service=new RefundBundleReturns();service.refunds=f.f.refunds;service.goods=f.goods;}
 @AfterEach void cleanup(){f.cleanup();}
 Map<String,Object> input(){Map<String,Object> input=f.version();input.putAll(m("bundle_id",bundle,"quantity",1,"store_code","V","return_address","TEST-ADDRESS","return_contact","TEST-CONTACT"));return input;}
 @Test void wholeSetCreatesSourceSpecificPlansAndRetriesDoNotDuplicate(){service.create("VERIFY",f.refund,input(),"test");assertEquals(2,f.f.db.queryForObject("SELECT COUNT(*) FROM oms_refund_return_plan",Integer.class));assertEquals(3,f.f.db.queryForObject("SELECT SUM(quantity) FROM oms_refund_return_plan",Long.class));service.create("VERIFY",f.refund,input(),"test");assertEquals(2,f.f.db.queryForObject("SELECT COUNT(*) FROM oms_refund_return_plan",Integer.class));List<Map<String,Object>> report=RefundBundleReturns.report(f.f.repo,"VERIFY",f.refund);assertEquals(3,number(report.get(0),"pending_quantity"));assertThrows(IllegalArgumentException.class,()->f.goods.finish("VERIFY",f.refund,f.version(),"test"));}
 @Test void onlyReturnedComponentsCannotCloseAnIncompleteWholeSetScope(){service.create("VERIFY",f.refund,input(),"test");f.f.db.update("DELETE FROM oms_refund_return_plan WHERE sku_sn='B'");f.f.db.update("UPDATE oms_refund_return_plan SET accepted_quantity=quantity,posted_quantity=quantity,state='CLOSED'");assertThrows(IllegalArgumentException.class,()->RefundBundleReturns.guardComplete(f.f.repo,"VERIFY",f.refund));assertEquals(1,number(RefundBundleReturns.report(f.f.repo,"VERIFY",f.refund).get(0),"pending_quantity"));}
 @Test void cannotCreateWholeSetFromInsufficientActualComponentShipment(){f.f.db.update("UPDATE oms_order_shipment_line SET shipped_quantity=0 WHERE sku_sn='B'");assertThrows(IllegalArgumentException.class,()->service.create("VERIFY",f.refund,input(),"test"));assertEquals(0,f.f.db.queryForObject("SELECT COUNT(*) FROM oms_refund_bundle_return",Integer.class));assertEquals(0,f.f.db.queryForObject("SELECT COUNT(*) FROM oms_refund_return_plan",Integer.class));}
 @Test void pendingWholeSetIntentClaimsSourceBeforeRemotePlanCreation(){RefundGoodsService unavailable=org.mockito.Mockito.mock(RefundGoodsService.class);org.mockito.Mockito.when(unavailable.create(org.mockito.ArgumentMatchers.anyString(),org.mockito.ArgumentMatchers.anyLong(),org.mockito.ArgumentMatchers.anyMap(),org.mockito.ArgumentMatchers.anyString())).thenThrow(new IllegalStateException("temporary"));service.goods=unavailable;assertThrows(IllegalStateException.class,()->service.create("VERIFY",f.refund,input(),"test"));assertEquals(0,f.f.db.queryForObject("SELECT COUNT(*) FROM oms_refund_return_plan",Integer.class));assertEquals(2,ReturnSourceClaims.refundUsed(f.f.repo,"VERIFY",f.source,0));assertEquals(0,ReturnSourceClaims.refundUsed(f.f.repo,"VERIFY",f.source,0,f.refund));service.goods=f.goods;service.create("VERIFY",f.refund,input(),"test");assertEquals(2,ReturnSourceClaims.refundUsed(f.f.repo,"VERIFY",f.source,0));}
}
